const CFG = {
  mode: 'multikeys',
  project_id: '',
  filter_tags: '',
  filter_filenames: '',
  filter_untranslated: 0,
  filter_lang_ids: '640,666,734,1056',
  grep: '(Garantierte Befriedigung|Probephase|Probeabo|prueba gratuita|Más acceso|Più accesso|declinato|periodo di prova di 4|wähle eine andere|Puoi annullare|Puedes cancelar cuando|Accedi ai tuoi)',
  key_ids: [],
  PIDS: ['1286096867dbf31146afc5.54950617','479073796a6095e8c10e35.09051894'],
  JOBS: []
};
const BASE = 'https://api.lokalise.com/api2';
if (CFG.mode === 'projects') return [{ json: { mode: 'projects', url: BASE + '/projects?limit=100' } }];
if (CFG.mode === 'languages') return [{ json: { mode: 'languages', url: BASE + '/projects/' + CFG.project_id + '/languages?limit=500' } }];
if (CFG.mode === 'files') return [{ json: { mode: 'files', url: BASE + '/projects/' + CFG.project_id + '/files?limit=500' } }];
let qs = 'include_translations=1&include_comments=1&disable_references=1&filter_archived=exclude&limit=500&pagination=cursor';
if (CFG.filter_lang_ids) qs += '&filter_translation_lang_ids=' + encodeURIComponent(CFG.filter_lang_ids);
if (CFG.mode === 'multikeys') return CFG.PIDS.map(p => ({ json: { mode: 'keys', grep: CFG.grep || '', url: BASE + '/projects/' + p + '/keys?' + qs } }));
if (CFG.mode === 'keynames') return CFG.JOBS.map(j => ({ json: { mode: 'keys', url: BASE + '/projects/' + j.pid + '/keys?' + qs + '&filter_keys=' + encodeURIComponent(j.names.join(',')) } }));
if (CFG.filter_tags) qs += '&filter_tags=' + encodeURIComponent(CFG.filter_tags);
if (CFG.filter_filenames) qs += '&filter_filenames=' + encodeURIComponent(CFG.filter_filenames);
if (CFG.filter_untranslated) qs += '&filter_untranslated=1';
if (CFG.mode === 'keycheck' && CFG.key_ids.length) qs += '&filter_key_ids=' + CFG.key_ids.join(',');
return [{ json: { mode: 'keys', grep: CFG.grep || '', url: BASE + '/projects/' + CFG.project_id + '/keys?' + qs } }];

const CFG = {
  mode: 'languages',
  project_id: '3070657967b5854be32cb1.65162854',
  filter_tags: '',
  filter_filenames: '',
  filter_untranslated: 0,
  filter_lang_ids: '',
  key_ids: [],
  PIDS: [],
  JOBS: []
};
const BASE = 'https://api.lokalise.com/api2';
if (CFG.mode === 'projects') return [{ json: { mode: 'projects', url: BASE + '/projects?limit=100' } }];
if (CFG.mode === 'languages') return [{ json: { mode: 'languages', url: BASE + '/projects/' + CFG.project_id + '/languages?limit=500' } }];
if (CFG.mode === 'files') return [{ json: { mode: 'files', url: BASE + '/projects/' + CFG.project_id + '/files?limit=500' } }];
let qs = 'include_translations=1&include_comments=1&disable_references=1&filter_archived=exclude&limit=500&pagination=cursor';
if (CFG.filter_lang_ids) qs += '&filter_translation_lang_ids=' + encodeURIComponent(CFG.filter_lang_ids);
if (CFG.mode === 'multikeys') return CFG.PIDS.map(p => ({ json: { mode: 'keys', url: BASE + '/projects/' + p + '/keys?' + qs } }));
if (CFG.mode === 'keynames') return CFG.JOBS.map(j => ({ json: { mode: 'keys', url: BASE + '/projects/' + j.pid + '/keys?' + qs + '&filter_keys=' + encodeURIComponent(j.names.join(',')) } }));
if (CFG.filter_tags) qs += '&filter_tags=' + encodeURIComponent(CFG.filter_tags);
if (CFG.filter_filenames) qs += '&filter_filenames=' + encodeURIComponent(CFG.filter_filenames);
if (CFG.filter_untranslated) qs += '&filter_untranslated=1';
if (CFG.mode === 'keycheck' && CFG.key_ids.length) qs += '&filter_key_ids=' + CFG.key_ids.join(',');
return [{ json: { mode: 'keys', url: BASE + '/projects/' + CFG.project_id + '/keys?' + qs } }];

const mode = $('Config').first().json.mode;
const grepSrc = $('Config').first().json.grep || '';
const grepRe = grepSrc ? new RegExp(grepSrc, 'i') : null;
const errors = [];
const pages = $input.all().map(i => i.json);
const bodies = [];
for (const p of pages) {
  const sc = p.statusCode;
  if (sc && sc >= 400) { errors.push({ status: sc, body: JSON.stringify(p.body).slice(0, 300) }); continue; }
  if (p.error) { errors.push({ error: String(p.error.message || p.error).slice(0, 300) }); continue; }
  bodies.push(p.body || p);
}
if (mode === 'files') {
  const files = [];
  for (const b of bodies) for (const f of (b.files || [])) files.push(f);
  return [{ json: { mode, errors, files } }];
}
if (mode === 'projects') {
  const projects = [];
  for (const b of bodies) for (const pr of (b.projects || [])) projects.push({ id: pr.project_id, name: pr.name, keys: pr.statistics && pr.statistics.keys_total, base: pr.base_language_iso });
  return [{ json: { mode, errors, projects } }];
}
if (mode === 'languages') {
  const langs = [];
  for (const b of bodies) for (const l of (b.languages || [])) langs.push(l.lang_iso);
  return [{ json: { mode, errors, langs } }];
}
let keysSeen = 0; const rows = []; const perProject = {};
for (const b of bodies) for (const k of (b.keys || [])) {
  keysSeen++;
  perProject[b.project_id || ''] = (perProject[b.project_id || ''] || 0) + 1;
  if (k.is_archived) continue;
  const name = typeof k.key_name === 'object' ? (k.key_name.web || k.key_name.other || Object.values(k.key_name)[0]) : k.key_name;
  const fn = k.filenames ? Object.values(k.filenames).filter(Boolean) : [];
  const row = { pid: b.project_id || '', id: k.key_id, k: name, pl: k.is_plural ? 1 : 0, fn,
    d: String(k.description || '').slice(0, 500), cl: Number(k.char_limit || 0),
    tg: Array.isArray(k.tags) ? k.tags.map(String) : [],
    c: (k.comments || []).map(x => String(x.comment || '')).filter(Boolean).join(' | ').slice(0, 300),
    en: '', em: '', t: {}, m: {}, ti: {}, e: {} };
  for (const tr of (k.translations || [])) {
    const iso = tr.language_iso;
    let txt = tr.translation;
    if (txt && typeof txt === 'object') txt = JSON.stringify(txt);
    if (iso === 'en') { row.en = txt || ''; row.em = tr.modified_at || ''; row.ti.en = tr.translation_id; row.e.en = tr.modified_by_email || ''; continue; }
    row.ti[iso] = tr.translation_id;
    row.m[iso] = (tr.modified_at || '') + '|' + (tr.is_reviewed ? 1 : 0) + '|' + (tr.is_unverified ? 1 : 0);
    row.e[iso] = tr.modified_by_email || '';
    if (txt) row.t[iso] = txt;
  }
  if (!row.en) continue;
  if (grepRe && !Object.values(row.t).some(v => grepRe.test(v))) continue;
  rows.push(row);
}
return [{ json: { mode, grep: grepSrc, keys_seen: keysSeen, per_project: perProject, rows_kept: rows.length, errors, rows } }];
